def compute_fill_range(row):
    """Given a row (with 1s, 7s, or 0s), compute (start, end) fill range"""
    cols = len(row)

    ones = [j for j, v in enumerate(row) if v == 1]
    sevens = [j for j, v in enumerate(row) if v == 7]

    # Case 1: 7 at start (col 0), fill from col 1 to end
    if row[0] == 7:
        return (1, cols - 1)

    # Case 2: 7 at end (rightmost), fill between first 1 and last 7
    if sevens and ones:
        if row[cols-1] == 7:
            return (min(ones) + 1, max(sevens) - 1)

    # Case 3: 1s on left (cols 0-4), fill from first 1+1 to end
    if ones and min(ones) < 5:
        return (min(ones) + 1, cols - 1)

    # Case 4: no 1s, no 7s at edges, fill from col 1 to end
    if any(v != 0 for v in row) and not ones:
        return (1, cols - 1)

    # Case 5: no 1s, no 7s at all
    return (None, None)

